const $=s=>document.querySelector(s), app=$('#app');
const KEY='shengdu-v1'; let state; try{state=JSON.parse(localStorage.getItem(KEY))||{}}catch(e){state={}}; state.words ||= [];state.reviews ||= {};state.checks ||= {};state.level ||= 'B1';state.speed ||= 0.9;
let page='home', current=null, sentenceIndex=0, masked=false, recording=null, audioUrl=null, modalWord='', modalIpa='', recChunks=[];
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
const day=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const plus=(n)=>{let d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const articles=Object.entries(banks).flatMap(([level,items])=>items.map((a,i)=>({id:level+'-'+i,level,title:a[0],zh:a[1],text:a[2]}))); const get=id=>articles.find(a=>a.id===id);
function due(){return Object.entries(state.reviews).filter(([id,x])=>x.next<=day()&&get(id));}
const navs=[['home','⌂','首页'],['library','▤','练习'],['reviews','◷','打卡'],['words','♡','生词本']];
function nav(){return navs.map(([id,icon,label])=>`<button class="${page===id?'active':''}" data-page="${id}"><span class="icon">${icon}</span>${label}</button>`).join('')}
function card(a){let r=state.reviews[a.id];return `<button class="article-card" data-open="${a.id}"><div class="card-top"><span class="pill">${a.level} · 原创练习</span><span>${r?'已开始':'短篇'}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.zh)} →</p></button>`}
function tasks(){const count=due().length, checks=state.checks[day()]||{};const rows=[['listen','听一遍文章','不看原文，先抓住大意'],['shadow','逐句跟读 3 遍','听一句、说一句、回听录音'],['recall','遮住原文尝试复述','卡住时看提示，再重新说'],['review',`复习到期内容${count?' · '+count+' 篇':''}`,count?'先回忆，再打开原文核对':'没有到期文章时，复习生词']];return rows.map(([id,t,sub])=>`<label class="task"><input type="checkbox" data-task="${id}" ${checks[id]?'checked':''}><span>${t}<small>${sub}</small></span></label>`).join('')}
function home(){let done=Object.values(state.checks[day()]||{}).filter(Boolean).length;let featured=articles.filter(x=>x.level===state.level).slice(0,4);return `<div class="layout"><div><section class="hero"><div class="tag">A LITTLE ENGLISH, EVERY DAY</div><h1>每天开口一点点，<br>听见自己的进步。</h1><p>从一篇感兴趣的短文开始，听、跟读、复述，再按节奏回来复习。</p><button class="btn" data-open="${featured[0].id}">开始今天的练习 &nbsp; ↗</button></section><div class="section-head"><div><h2>为你准备的练习</h2><p>选一篇，慢慢读给自己听</p></div><button class="link" data-page="library">查看全部 →</button></div><div class="grid">${featured.map(card).join('')}</div><p class="hint">40 篇原创新闻风格短文，用于口语练习；内容为模拟情境，并非实时新闻。</p></div><aside class="right-column"><div class="right-card"><div class="date-row"><h3>今日小任务</h3><span class="pill">${done} / 4</span></div><p>每天一点，记得更牢。</p><div class="mini-progress"><span style="width:${done*25}%"></span></div>${tasks()}<button class="link" data-page="reviews">查看复习计划 →</button></div><div class="right-card quote"><div class="mark">“</div><strong>Little by little,<br>a little becomes a lot.</strong><p>一点一滴，终将汇成很多。</p></div></aside></div>`}
function library(){return `<div class="page-header"><div class="eyebrow">THE READING ROOM</div><h1>练习文章</h1><p class="sub">按难度选择你想听、想读、想记住的内容。</p></div><div class="tabs">${['B1','B2','C1','C2'].map(x=>`<button data-level="${x}" class="${state.level===x?'active':''}">${x} · ${x==='B1'?'进阶入门':x==='B2'?'中高级':x==='C1'?'高级':'精通'}</button>`).join('')}</div><div class="notice">每级 10 篇，共 40 篇。当前是原创模拟新闻风格的短篇素材，适合先练方法；它们不是实时新闻，也未达到每篇 3 分钟。</div><div class="grid">${articles.filter(a=>a.level===state.level).map(card).join('')}</div>`}
function sentences(a){return a.text.match(/[^.!?]+[.!?]+/g)?.map(s=>s.trim())||[a.text]}
function tokenize(s){return s.replace(/([A-Za-z]+(?:['’-][A-Za-z]+)*)/g,'<span class="word" data-word="$1">$1</span>')}
function reading(){let a=get(current);if(!a)return library();let ss=sentences(a);sentenceIndex=Math.max(0,Math.min(sentenceIndex,ss.length-1));let r=state.reviews[a.id];return `<div class="reading"><button class="back" data-page="library">← 返回文章</button><div class="page-header"><div class="eyebrow" style="margin-top:25px">LISTEN · SHADOW · REMEMBER</div><h1>${esc(a.title)}</h1><p class="sub">${a.level} &nbsp; / &nbsp; ${esc(a.zh)} &nbsp; / &nbsp; 原创模拟短篇</p></div><div class="toolbar"><button class="btn" data-action="play-all">▶ &nbsp; 听全文</button><button class="btn light" data-action="stop">■ &nbsp; 停止</button><label class="speed">速度 <select id="speed" style="border:0;background:transparent;color:inherit"><option value="0.7">0.7×</option><option value="0.8">0.8×</option><option value="0.9">0.9×</option><option value="1">1.0×</option><option value="1.2">1.2×</option></select></label><button class="btn secondary" data-action="mask">${masked?'显示原文':'遮住原文'}</button></div><p class="hint">长按单词直接听发音；轻点单词查看音标并加入生词本。点句子可切换跟读目标。</p><div class="box"><div class="textblock">${ss.map((s,i)=>`<span class="sentence ${i===sentenceIndex?'selected':''}" data-sentence="${i}">${masked?'● ● ● ● ● ●':tokenize(esc(s))}</span> `).join('')}</div></div><div class="training"><div class="date-row"><h3>逐句跟读 <span style="color:#86a08b;font-weight:400">${sentenceIndex+1} / ${ss.length}</span></h3><span class="pill">SHADOWING</span></div><p>${masked?'试着凭记忆说出这一句。':esc(ss[sentenceIndex])}</p><div class="row"><button class="btn secondary" data-action="prev">← 上一句</button><button class="btn secondary" data-action="play-sentence">▶ 听这句</button><button class="btn secondary" data-action="next">下一句 →</button><button class="btn" data-action="record">● 录音</button><button class="btn light" data-action="stop-record">■ 结束</button><button class="btn light" data-action="play-record">▷ 回听</button></div><p id="rec-status" class="hint">先听原音，再录下自己的声音，回听比较节奏和连读。</p></div><div class="notice">朗读使用设备可用的英语语音，优先选择美式英语；音色和自然度取决于设备。录音只在本次页面使用，本版本不提供专业发音评分。</div><div class="box"><div class="date-row"><div><h3 style="margin:0;font-size:15px">加入间隔复习</h3><p class="hint">${r?`当前第 ${r.stage+1} 次复习 · 下次 ${r.next}`:'完成首次学习后加入计划'}</p></div><button class="btn" data-action="start-review">${r?'重设计划':'加入复习'}</button></div></div><div class="box"><h3 style="font-size:15px;margin:0">连读小课堂</h3><p class="hint">下面是常见的美式语流示例；实际读法会因语速、语境和说话人而变化。</p>${tips.map(t=>`<div class="tip"><strong>${t.phrase}</strong><span>${t.ipa}</span><p><b>${t.title}：</b>${t.explain}</p><button class="link" data-say="${t.phrase}">▶ 听示例</button></div>`).join('')}</div></div>`}
function reviewPage(){let rows=Object.entries(state.reviews).filter(([id])=>get(id)).sort((a,b)=>a[1].next.localeCompare(b[1].next));return `<div class="page-header"><div class="eyebrow">YOUR ROUTINE</div><h1>今天也来打个卡</h1><p class="sub">先回忆，再核对。每次短一点，也比只读一遍更有用。</p></div><div class="layout"><div><div class="box"><div class="date-row"><h3 style="margin:0">今日练习</h3><span class="pill">${day()}</span></div>${tasks()}</div><div class="section-head"><div><h2>间隔复习</h2><p>到期后凭记忆复述，核对后标记完成</p></div></div><div class="box">${rows.length?rows.map(([id,r])=>{let a=get(id);return `<div class="word-row"><div><b>${esc(a.title)}</b><small>${a.level} · ${r.next<=day()?'今天应复习':'下次 '+r.next} · 第 ${r.stage+1} 次</small></div><div class="row"><button class="link" data-open="${id}">打开</button><button class="btn secondary" data-done="${id}" ${r.next>day()?'disabled':''}>完成复习</button></div></div>`}).join(''):'<div class="empty">还没有复习计划。打开一篇文章，点击「加入复习」。</div>'}</div><div class="notice">复习间隔采用 1、2、4、7、15 天的实用安排，借鉴间隔复习思路；并非人人适用的固定遗忘曲线。每次完成后才安排下一次。</div></div><aside><div class="right-card"><h3>怎么练更有效？</h3><p>① 先盲听抓大意<br>② 逐句模仿并回听<br>③ 遮住原文尝试复述<br>④ 复习时先回想，再看答案</p></div><div class="right-card"><h3>数据与设备</h3><p>进度保存在当前浏览器，不会自动在 iPhone 和 iPad 同步。你可以导出数据，再在另一台设备导入。</p><div class="row"><button class="btn secondary" data-action="export">导出数据</button><button class="btn light" data-action="import">导入数据</button><input id="import" class="file-input" type="file" accept="application/json"></div></div></aside></div>`}
function wordsPage(){return `<div class="page-header"><div class="eyebrow">MY VOCABULARY</div><h1>我的生词本</h1><p class="sub">把不熟悉的词留下来，常回来听一听。</p></div><div class="box"><div class="row"><input id="new-word" placeholder="输入英文单词" style="flex:1;min-width:150px;border:1px solid var(--line);border-radius:10px;padding:12px"><button class="btn" data-action="add-manual">添加单词</button></div>${state.words.length?state.words.map(w=>`<div class="word-row"><div><strong>${esc(w.word)}</strong><small>${esc(w.ipa||'点击查看音标')} ${esc(w.meaning||'')}</small></div><div class="row"><button class="link" data-word="${esc(w.word)}">查看 / 听</button><button class="link" data-delete="${esc(w.word)}">删除</button></div></div>`).join(''):'<div class="empty">生词本还是空的。<br>在文章里点一个单词，就能把它加进来。</div>'}</div>`}
function render(){let view=page==='home'?home():page==='library'?library():page==='reading'?reading():page==='reviews'?reviewPage():wordsPage();app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="logo">◒</span><div>声读英语<small>SPEAK A LITTLE</small></div></div><div class="side-label">YOUR LEARNING SPACE</div><nav class="nav">${nav()}</nav><div class="side-bottom"><strong>练习，不必着急。</strong><br>每一次开口，都是在为下一次积累。</div></aside><main class="main"><div class="top"><div><div class="eyebrow">YOUR ENGLISH MOMENT</div><div class="top-title">留一点时间，给更自信的自己。</div></div><div class="top-right">慢慢来，比较快 <span class="avatar">✳</span></div></div>${view}</main><nav class="bottom-nav">${nav()}</nav></div>`;let sp=$('#speed');if(sp)sp.value=state.speed;window.scrollTo(0,0)}
function speak(s){if(!('speechSynthesis'in window)){alert('当前浏览器不支持朗读，请尝试 Safari。');return} speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(s);u.lang='en-US';u.rate=Number(state.speed);let voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang.toLowerCase()==='en-us' && /samantha|american/i.test(v.name))||voices.find(v=>v.lang.toLowerCase()==='en-us')||null;speechSynthesis.speak(u)}
async function wordModal(word){modalWord=word.toLowerCase();modalIpa='';$('.modal-bg')?.remove();let bg=document.createElement('div');bg.className='modal-bg';bg.innerHTML=`<div class="modal"><button class="close" data-close>✕</button><div class="eyebrow">WORD NOTE</div><h2>${esc(modalWord)}</h2><div class="phonetic" id="ipa">正在查询音标…</div><p id="definition">音标和释义需要联网查询；未查到时仍可听设备发音。</p><div class="row"><button class="btn" data-say="${esc(modalWord)}">▶ 听发音</button><button class="btn secondary" data-action="save-word">♡ 加入生词本</button><button class="btn light" data-action="record">● 录音</button><button class="btn light" data-action="stop-record">■ 结束</button><button class="btn light" data-action="play-record">▷ 回听</button></div><p id="rec-status-modal" class="hint">听原音后录音，回听比较。发音评分暂不可用。</p></div>`;document.body.append(bg);try{let response=await fetch('https://api.dictionaryapi.dev/api/v2/entries/en/'+encodeURIComponent(modalWord));if(!response.ok)throw 0;let d=await response.json();if(!document.body.contains(bg))return;let entry=d[0];modalIpa=entry.phonetic||entry.phonetics?.find(p=>p.text)?.text||'';$('#ipa').textContent=modalIpa||'未找到音标';$('#definition').textContent=entry.meanings?.[0]?.definitions?.[0]?.definition||'未找到释义';}catch(e){if(document.body.contains(bg)){$('#ipa').textContent='暂未查到音标';$('#definition').textContent='词典服务暂时不可用，请检查网络后重试。'}}}
async function recordStart(){try{if(recording?.state==='recording')return;let stream=await navigator.mediaDevices.getUserMedia({audio:true});recording=new MediaRecorder(stream);recChunks=[];recording.ondataavailable=e=>{if(e.data.size)recChunks.push(e.data)};recording.onstop=()=>{if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=URL.createObjectURL(new Blob(recChunks,{type:recording.mimeType||'audio/mp4'}));stream.getTracks().forEach(t=>t.stop());status('录音已保存到本次页面，点击「回听」比较。')};recording.start();status('正在录音… 完成后点击「结束」。')}catch(e){status('无法录音。请允许麦克风权限，并使用支持录音的 Safari。')}}
function status(s){document.querySelectorAll('#rec-status,#rec-status-modal').forEach(el=>el.textContent=s)}
function saveWord(w,ipa=''){w=w.trim().toLowerCase();if(!/^[a-z]+(?:['’-][a-z]+)*$/i.test(w)){alert('请输入一个英文单词。');return}if(!state.words.some(x=>x.word===w))state.words.unshift({word:w,ipa});else if(ipa)state.words.find(x=>x.word===w).ipa=ipa;save()}
app.addEventListener('change',e=>{if(e.target.id==='speed'){state.speed=e.target.value;save()}if(e.target.dataset.task){state.checks[day()]||={};state.checks[day()][e.target.dataset.task]=e.target.checked;save();render()}if(e.target.id==='import'){let f=e.target.files[0];if(!f)return;let fr=new FileReader();fr.onload=()=>{try{let obj=JSON.parse(fr.result);if(!Array.isArray(obj.words)||typeof obj.reviews!=='object'||typeof obj.checks!=='object')throw Error();if(!confirm('导入会覆盖本设备当前的学习数据，继续吗？'))return;state=obj;state.level||='B1';state.speed||=0.9;save();render();alert('导入成功。')}catch(err){alert('文件格式不正确。请选择从声读英语导出的数据文件。')}};fr.readAsText(f)}});
document.addEventListener('click',e=>{let el=e.target.closest('button,[data-word],[data-sentence]');if(!el)return;if(el.dataset.close!==undefined){$('.modal-bg')?.remove();return}if(el.dataset.word){e.stopPropagation();wordModal(el.dataset.word);return}if(el.dataset.sentence!==undefined){sentenceIndex=Number(el.dataset.sentence);render();return}if(el.dataset.page){page=el.dataset.page;render();return}if(el.dataset.open){current=el.dataset.open;page='reading';sentenceIndex=0;masked=false;render();return}if(el.dataset.level){state.level=el.dataset.level;save();render();return}if(el.dataset.say){speak(el.dataset.say);return}if(el.dataset.delete){state.words=state.words.filter(x=>x.word!==el.dataset.delete);save();render();return}if(el.dataset.done){let r=state.reviews[el.dataset.done], intervals=[1,2,4,7,15];r.stage++;r.next=plus(intervals[Math.min(r.stage,intervals.length-1)]);save();render();return}let a=el.dataset.action;if(!a)return;if(a==='play-all')speak(get(current).text);if(a==='stop')speechSynthesis.cancel();if(a==='play-sentence')speak(sentences(get(current))[sentenceIndex]);if(a==='prev'){sentenceIndex--;render()}if(a==='next'){sentenceIndex++;render()}if(a==='mask'){masked=!masked;render()}if(a==='record')recordStart();if(a==='stop-record'){if(recording?.state==='recording')recording.stop();else status('请先点击「录音」。')}if(a==='play-record'){if(audioUrl)new Audio(audioUrl).play().catch(()=>status('无法播放录音，请重新录制。'));else status('还没有录音，请先录音并结束。')}if(a==='start-review'){if(state.reviews[current]&&!confirm('重新开始会重设这篇文章的复习日期，继续吗？'))return;state.reviews[current]={stage:0,next:plus(1)};save();render()}if(a==='save-word'){saveWord(modalWord,modalIpa);el.textContent='✓ 已加入';}if(a==='add-manual'){let w=$('#new-word').value;saveWord(w);render()}if(a==='export'){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='shengdu-progress.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}if(a==='import')$('#import').click()});
let hold;document.addEventListener('touchstart',e=>{let w=e.target.closest('[data-word]');if(w)hold=setTimeout(()=>{hold=null;speak(w.dataset.word);wordModal(w.dataset.word)},550)},{passive:true});document.addEventListener('touchend',()=>{if(hold)clearTimeout(hold)},{passive:true});document.addEventListener('touchmove',()=>{if(hold)clearTimeout(hold)},{passive:true});
render();
